    self.NowPlaying.playing:Insert(2, NEW("Playing", 1, false, "", "Tension", 1, 0, "a", "", "", true, "Cyan", false, ""))
    self.NowPlaying.playing:Insert(3, NEW("Playing", 1, false, "", "Tension", 1, 0, "a", "", "", true, "LightGreen", false, ""))
