    self.NowPlaying.playing:Insert(5, NEW("Playing", 1, false, "", "Tension", 1, 0, "a", "", "", true, "Orange", false, ""))
    self.NowPlaying.playing:Insert(6, NEW("Playing", 1, false, "", "Tension", 1, 0, "a", "", "", true, "Magenta", false, ""))
    self.NowPlaying.playing:Insert(7, NEW("Playing", 1, false, "", "Tension", 1, 0, "a", "", "", true, "Red", false, ""))
    return 1
  end
  local status = StatusManager:GetStatus("Follower")
  local alphaLevel = EventManager.alphaLevel
  local num = TRUNC(Math.Max(1, Math.Log10(status) * alphaLevel / 2))
  do
    local i = 0
