      local nakami = self:FetchComment(EventManager.alpha, "akaruku", haisinPoint, status, alphaLevel)
      local item = NEW("Playing", 1, false, nakami, "Tension", 1, 0, "", "", "", true, "White", false, "")
      self.NowPlaying.playing:Insert(i + 1, item)
      i = i + 1
    end
  end
  return 1
end

function C.GetMobCommentList(haishinPos, follower)
  local mobs = NgoEx.getMobs()
  local rank = 1
  if follower > 100000 then
    rank = 3
  elseif follower > 10000 then
    rank = 2
  end
  if mobs then
    return mobs.param:Where(function(c) return (c.Rank == rank and c.timing == haishinPos) or (c.Rank == 0 and c.timing == haishinPos) end):ToList()
  end
  return nil
end

function C:FetchComment(alpha, beta, haisinPos, follower, tension)
  local mobCommentList = Live.GetMobCommentList(haisinPos, follower)
  local index = Random.Range(0, mobCommentList.Count - 1)
  return (function(__v2) if __v2 == "JP" then return IDX(mobCommentList, index).BodyJP end if __v2 == "CN" then return IDX(mobCommentList, index).BodyCh end if __v2 == "KO" then return IDX(mobCommentList, index).BodyKo end if __v2 == "TW" then return IDX(mobCommentList, index).BodyTw end if __v2 == "VN" then return IDX(mobCommentList, index).BodyVn end if __v2 == "FR" then return IDX(mobCommentList, index).BodyFr end if __v2 == "IT" then return IDX(mobCommentList, index).BodyIt end if __v2 == "GE" then return IDX(mobCommentList, index).BodyGe end if __v2 == "SP" then return IDX(mobCommentList, index).BodySp end if __v2 == "RU" then return IDX(mobCommentList, index).BodyRu end if true then return IDX(mobCommentList, index).BodyEn end end)(self._lang)
end

function C:bgView()
