function C:ReadComment()
  self.isStartRead = true
  self.NowPlaying.isGensoku.Value = false
  self:RefreshYomuCommentLabel()
  if self.ReadCommentParent.childCount == 0 then
    return
  end
  local list = NEW("List", nil)
  if self:isYomiReactionExist(EventManager.alpha, EventManager.alphaLevel) then
    local readAnimationFromHaishin = self:getReadAnimationFromHaishin(EventManager.alpha, EventManager.alphaLevel)
    if readAnimationFromHaishin ~= "" then
      list:Add(NEW("Playing", 1, true, NgoEx.TenTalk_2(IDX(self.ReadingSerihu, Random.Range(0, self.ReadingSerihu.Count)), Settings.CurrentLanguage.Value), "Tension", 1, 0, "", "", readAnimationFromHaishin, true, "White", false, ""))
    else
      list:Add(NEW("Playing", 1, true, NgoEx.TenTalk_2(IDX(self.ReadingSerihu, Random.Range(0, self.ReadingSerihu.Count)), Settings.CurrentLanguage.Value), "Tension", 1, 0, "", "", "", true, "White", false, ""))
    end
  end
  do
    local i = 1
    while i <= self.ReadCommentParent.childCount do
      local playing = self.ReadCommentParent:GetChild(i - 1):GetComponent("LiveComment").playing
      local text = ((function() if (Settings.CurrentLanguage.Value == "EN") then return "“" else return "「" end end)())
      local text2 = ((function() if (Settings.CurrentLanguage.Value == "EN") then return "”" else return "」" end end)())
      list:Add(NEW("Playing", 1, true, CONCAT(CONCAT(text, playing.nakami), text2), "Tension", playing.additionalTension, 0, "", "", "", true, "White", false, ""))
      if playing.henji ~= "" then
        self:SuperChattedChotenAnim()
        local _ = playing.henjiAnim ~= ""
        local array = STR.Split(playing.henji, Live.separator, "RemoveEmptyEntries")
        local array2 = STR.Split(playing.henjiAnim, Live.separator, "None")
        do
          local j = 0
          while j < array.Length do
            list:Add(NEW("Playing", 1, true, IDX(array, j), "Tension", 1, 0, "", "", IDX(array2, Math.Max(0, Math.Min(j, array2.Length - 1))), playing.isLoopAnim, "White", false, ""))
            j = j + 1
          end
        end
      end
      i = i + 1
    end
  end
  self.NowPlaying.playing:InsertRange(1, list)
end

function C:ShowJimaku(playing)
  if not coroutine.isyieldable() then spawn(C.ShowJimaku, self, playing) return end
  local num = ((function() if self.isHayakuti then return 0.02 else return 0.05 end end)())
  if Settings.CurrentLanguage.Value == "EN" or Settings.CurrentLanguage.Value == "FR" or Settings.CurrentLanguage.Value == "IT" or Settings.CurrentLanguage.Value == "GE" or Settings.CurrentLanguage.Value == "SP" or Settings.CurrentLanguage.Value == "RU" then
    Canvas.ForceUpdateCanvases()
    self.jimakuLayout:SetLayoutVertical()
    self.jimakuLayout:SetLayoutHorizontal()
    self:SetJimakuPostion(self.jimakuLayout.gameObject, self.jimakuShowing.text)
  end
  self.jimakuShowing.text = ""
  local endValue = STR.Replace(playing.nakami, "<br>", "\n")
  self.Jimaku = self.jimakuShowing:DOText(endValue, STR.Length(playing.nakami) * num, true, "None"):SetEase("Linear")
  self.isSpeaking = true
  self.Jimaku:Play()
  UniTask.Delay(IDIV(Constants.FAST, 8), false, "Update", nil, false)
  self.isSpeaking = false
end

function C:SetJimakuPostion(jimakuTransform, showText)
  showText = Regex.Replace(showText, "<br\\s*/*>", "\n", "IgnoreCase")
  showText = STR.Replace(showText, "\r\n", "\n")
  local num = LCOUNT(showText, function(c) return c == "\n" end) + 1
  local component = jimakuTransform:GetComponent("RectTransform")
  repeat
    local __sw7 = num
    if __sw7 == 4 then
      component.anchoredPosition = NEW("Vector3", nil, 0, 75, 0)
    elseif __sw7 == 5 then
      component.anchoredPosition = NEW("Vector3", nil, 0, 95, 0)
    elseif __sw7 == 6 then
      component.anchoredPosition = NEW("Vector3", nil, 0, 115, 0)
    else
      component.anchoredPosition = NEW("Vector3", nil, 0, 55, 0)
    end
  until true
end

function C:NextSerihu()
  if self.isSpeaking then
    self.Jimaku:Kill(true)
  else
    self.NowPlaying:PlayScenarioToNextSerihu()
  end
end

function C:NewComment(playing)
  local component = self.CommentParent:GetChild(self.commentCounter):GetComponent("LiveComment")
  self._selectableComments:Add(component)
  component.gameObject:SetActive(true)
  spawn(function() component:SetContent(playing, false) end)
  self:UpdateDetail()
  self.CommentScroll.verticalNormalizedPosition = 0
  self.commentCounter = self.commentCounter + 1
end

function C:CommentScrollToLatest()
  self.CommentScroll.verticalNormalizedPosition = 0
end

function C:CommentScrollToTarget(targetComment)
  local component = targetComment:GetComponent("RectTransform")
  local anchoredPosition = component.anchoredPosition
  local y = component.sizeDelta.y
  local anchoredPosition2 = self.CommentParent.anchoredPosition
  self.CommentParent.anchoredPosition = NEW("Vector2", nil, anchoredPosition2.x, anchoredPosition.y * -1 - y)
end

function C:isActiveReaction()
  if self.isUncontrollable or self.isStartRead or self.isOiwai then
    self:setCursor(1)
    self.NowPlaying.isGensoku.Value = false
    return false
  end
  return true
end

function C:Actioned()
  self.cooltime = 0
  if self.isUncontrollable or self.isStartRead or self.isOiwai then
    self:setCursor(1)
  end
end

function C:setCursor(time)
  if time >= 0 then
    if time == 1 then
      CursorManager:SetCursor(self.Countdown1, self.hotSpot, self.cursorMode)
    else
      CursorManager:SetCursor(nil, self.hotSpot, self.cursorMode)
    end
  end
end

function C:EndHaishin()
  self.NowPlaying.isGensoku.Value = false
  CursorManager:SetCursor(nil, self.hotSpot, self.cursorMode)
  if self.isGuideEnable then
    ControllerGuideManager:RemoveActiveLiveApp()
    ControllerGuideManager.IsReady = false
  end
  ShortcutInputManager:ChangeControllerMode("Desktop")
  self.statusDiffs:Clear()
  EventManager:EndHaishin()
  CursorManager:DisableLiveCursorMode()
end

function C:HaishinClean()
  self.NowPlaying.isGensoku.Value = false
  CursorManager:SetCursor(nil, self.hotSpot, self.cursorMode)
  if self.isGuideEnable then
    ControllerGuideManager:RemoveActiveLiveApp()
    ControllerGuideManager.IsReady = false
  end
  ShortcutInputManager:ChangeControllerMode("Desktop")
  self.statusDiffs:Clear()
  EventManager:HaishinClean()
end

return C
